originalCss:
:root {
    --bg: #07111e;
    --panel: #0d1b2e;
    --card: #12233b;
    --line: #25405f;
    --text: #e6eefc;
    --dim: #c7d6ec;
    --faint: #9cb0cf;
    --accent: #7c9eff;
    --sw: 280px;
}
* {
    box-sizing: border-box;
}
html {
    scroll-behavior: smooth;
    overflow-x: hidden;
}
body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font-family:
        'Noto Sans JP',
        -apple-system,
        'Hiragino Kaku Gothic ProN',
        'Yu Gothic',
        Meiryo,
        sans-serif;
    font-size: 16px;
    line-height: 1.85;
    overflow-x: hidden;
}
.sidebar {
    position: fixed;
    left: 0;
    top: 0;
    bottom: 0;
    width: var(--sw);
    background: var(--panel);
    border-right: 1px solid var(--line);
    overflow-y: auto;
    padding: 20px 14px;
    z-index: 20;
}
.side-title {
    font-weight: 800;
    color: var(--accent);
    font-size: 15px;
    margin-bottom: 14px;
    letter-spacing: 0.02em;
}
.sidebar nav a {
    display: block;
    color: var(--faint);
    text-decoration: none;
    font-size: 13.5px;
    line-height: 1.5;
    padding: 6px 10px;
    border-radius: 6px;
    border-left: 2px solid transparent;
}
.sidebar nav a.nav-h3 {
    padding-left: 22px;
    font-size: 12.5px;
}
.sidebar nav a:hover {
    color: var(--text);
    background: #12233b;
}
.sidebar nav a.active {
    color: #fff;
    background: #16304f;
    border-left-color: var(--accent);
}
.main {
    margin-left: var(--sw);
    padding: 40px 48px 80px;
}
.hero {
    position: relative;
    border: 1px solid var(--line);
    background: linear-gradient(180deg, #0f2038, #0b1829);
    border-radius: 16px;
    padding: 32px 36px;
    margin-bottom: 36px;
    overflow: hidden;
}
.hero::before {
    content: '';
    position: absolute;
    top: -80px;
    right: -80px;
    width: 300px;
    height: 300px;
    background: radial-gradient(circle, rgba(124, 158, 255, 0.28), transparent 70%);
}
.eyebrow {
    display: inline-block;
    font-size: 12px;
    font-weight: 700;
    color: var(--accent);
    border: 1px solid var(--accent);
    border-radius: 999px;
    padding: 3px 14px;
    margin-bottom: 14px;
}
.hero-title {
    margin: 0 0 18px;
    font-size: 28px;
    font-weight: 800;
    color: #fff;
    line-height: 1.4;
    position: relative;
}
.hero-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0;
    position: relative;
}
.hero-meta p {
    margin: 0;
    padding: 4px 18px;
    border-right: 1px solid var(--line);
    font-size: 13.5px;
    color: var(--dim);
    flex: 1 1 260px;
}
.hero-meta p:last-child {
    border-right: none;
}
h2 {
    font-size: 23px;
    font-weight: 800;
    margin: 56px 0 16px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--line);
    color: #fff;
    scroll-margin-top: 16px;
}
h3 {
    font-size: 18.5px;
    font-weight: 700;
    margin: 34px 0 12px;
    color: var(--accent);
    scroll-margin-top: 16px;
}
h4 {
    font-size: 16.5px;
    margin: 26px 0 10px;
    color: var(--text);
}
p,
ul,
ol {
    color: var(--dim);
}
strong {
    color: #fff;
}
a {
    color: var(--accent);
    word-break: break-all;
}
hr {
    border: none;
    border-top: 1px solid var(--line);
    margin: 36px 0;
}
code {
    font-family: 'JetBrains Mono', ui-monospace, monospace;
    font-size: 0.88em;
    background: #0d1b2e;
    border: 1px solid var(--line);
    border-radius: 5px;
    padding: 1px 6px;
    color: #bcd0ff;
    overflow-wrap: break-word;
    word-break: break-word;
}
blockquote {
    margin: 20px 0;
    padding: 14px 20px;
    background: var(--panel);
    border-left: 4px solid var(--accent);
    border-radius: 0 10px 10px 0;
}
blockquote p {
    margin: 6px 0;
    color: var(--dim);
}
.table-scroll {
    overflow-x: auto;
    margin: 18px 0;
    border: 1px solid var(--line);
    border-radius: 10px;
}
table {
    border-collapse: collapse;
    width: 100%;
    font-size: 14.5px;
}
th {
    background: #16304f;
    color: #fff;
    text-align: left;
    font-weight: 700;
}
th,
td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--line);
    vertical-align: top;
    color: var(--dim);
}
td strong {
    color: #fff;
}
tr:last-child td {
    border-bottom: none;
}
tbody tr:nth-child(even) {
    background: rgba(255, 255, 255, 0.02);
}
ul li input[type='checkbox'] {
    margin-right: 8px;
    accent-color: var(--accent);
}
li {
    margin: 4px 0;
}
.mermaid-diagram {
    display: block;
    overflow-x: auto;
    border: 1px solid var(--line);
    background: var(--panel);
    border-radius: 12px;
    padding: 20px;
    margin: 22px 0;
}
.mermaid-diagram svg {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: none;
    flex-shrink: 0;
}
.mermaid-diagram foreignObject div,
.mermaid-diagram foreignObject span,
.mermaid-diagram foreignObject p {
    white-space: normal !important;
}
.mermaid-diagram foreignObject {
    overflow: visible;
}
.mermaid-diagram p {
    color: inherit;
    margin: 0;
}
.page-footer {
    margin-top: 60px;
    padding-top: 20px;
    border-top: 1px solid var(--line);
    color: var(--faint);
    font-size: 13px;
}
.nav-toggle {
    display: none;
    position: fixed;
    top: 12px;
    left: 12px;
    z-index: 30;
    background: var(--card);
    color: var(--text);
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 8px 14px;
    font: inherit;
    font-size: 14px;
}
@media (max-width: 900px) {
    .nav-toggle {
        display: block;
    }
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.2s;
    }
    .sidebar.open {
        transform: none;
    }
    .main {
        margin-left: 0;
        padding: 64px 16px 60px;
    }
    .hero {
        padding: 22px 18px;
    }
    .hero-title {
        font-size: 22px;
    }
    .hero-meta p {
        border-right: none;
        border-bottom: 1px solid var(--line);
    }
}

.checklist-card {
    border: 1px solid var(--line);
    background: linear-gradient(180deg, #0f2038, #0b1829);
    border-radius: 14px;
    padding: 20px 22px;
    margin: 20px 0;
}
.checklist-progress {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 18px;
    position: sticky;
    top: 0;
}
.cp-label {
    font-size: 13px;
    font-weight: 700;
    color: var(--accent);
}
.cp-bar {
    flex: 1;
    height: 10px;
    background: #0d1b2e;
    border: 1px solid var(--line);
    border-radius: 999px;
    overflow: hidden;
}
.cp-fill {
    height: 100%;
    width: 0;
    background: linear-gradient(90deg, #4f78e8, #7c9eff);
    border-radius: 999px;
    transition: width 0.25s;
}
.cp-count {
    font-family: 'JetBrains Mono', monospace;
    font-size: 13px;
    color: var(--dim);
    min-width: 52px;
    text-align: right;
}
.check-group {
    margin-top: 18px;
}
.cg-title {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 10px;
}
.cg-icon {
    font-size: 20px;
}
.cg-phase {
    font-size: 11px;
    font-weight: 700;
    color: var(--accent);
    border: 1px solid var(--accent);
    border-radius: 999px;
    padding: 1px 10px;
}
.cg-name {
    font-weight: 700;
    color: #fff;
    font-size: 15px;
}
ul.check-grid {
    list-style: none;
    margin: 0;
    padding: 0;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
}
.check-item {
    margin: 0;
}
.check-item label {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    height: 100%;
    padding: 12px 14px;
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 10px;
    cursor: pointer;
    color: var(--dim);
    transition:
        border-color 0.15s,
        background 0.15s;
}
.check-item label:hover {
    border-color: var(--accent);
    background: #16304f;
}
.check-item input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}
.ci-box {
    flex: 0 0 22px;
    height: 22px;
    margin-top: 2px;
    border: 2px solid var(--faint);
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    color: transparent;
    font-weight: 800;
}
.ci-num {
    flex: 0 0 auto;
    font-family: 'JetBrains Mono', monospace;
    font-size: 12px;
    color: var(--faint);
    margin-top: 4px;
}
.ci-text {
    font-size: 14.5px;
    line-height: 1.6;
    overflow-wrap: break-word;
    min-width: 0;
}
.check-item input:checked ~ .ci-box {
    background: var(--accent);
    border-color: var(--accent);
    color: #07111e;
}
.check-item input:checked ~ .ci-text {
    color: var(--faint);
    text-decoration: line-through;
    text-decoration-color: var(--faint);
}
.check-item label:has(input:checked) {
    border-color: #4f78e8;
    background: #12294a;
}
.check-item input:focus-visible ~ .ci-box {
    outline: 2px solid #fff;
    outline-offset: 2px;
}
.cp-done {
    margin-top: 18px;
    padding: 12px 16px;
    border: 1px solid var(--accent);
    background: #12294a;
    border-radius: 10px;
    color: #fff;
    font-weight: 700;
}
@media (max-width: 700px) {
    ul.check-grid {
        grid-template-columns: minmax(0, 1fr);
    }
}
